import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"62、【小过】 艮下震上","description":"横渠易说 - 62、【小过】 艮下震上","frontmatter":{"title":"62、【小过】 艮下震上","description":"横渠易说 - 62、【小过】 艮下震上"},"headers":[],"relativePath":"zh/classics/hengqu/064.md","filePath":"zh/classics/hengqu/064.md"}'),l={name:"zh/classics/hengqu/064.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_62、【小过】-艮下震上" tabindex="-1">62、【小过】 艮下震上 <a class="header-anchor" href="#_62、【小过】-艮下震上" aria-label="Permalink to “62、【小过】 艮下震上”">​</a></h1><h3 id="彖曰-小过-小者过而亨也-过以利贞-与时行也。柔得中-是以小事吉也-刚失位而不中-是以不可大事也。有飞鸟之象焉-飞鸟遗之音-不宜上宜下大吉-上逆而下顺也。" tabindex="-1">彖曰：小过，小者过而亨也，过以利贞，与时行也。柔得中，是以小事吉也；刚失位而不中，是以不可大事也。有飞鸟之象焉，“飞鸟遗之音，不宜上宜下大吉”，上逆而下顺也。 <a class="header-anchor" href="#彖曰-小过-小者过而亨也-过以利贞-与时行也。柔得中-是以小事吉也-刚失位而不中-是以不可大事也。有飞鸟之象焉-飞鸟遗之音-不宜上宜下大吉-上逆而下顺也。" aria-label="Permalink to “彖曰：小过，小者过而亨也，过以利贞，与时行也。柔得中，是以小事吉也；刚失位而不中，是以不可大事也。有飞鸟之象焉，“飞鸟遗之音，不宜上宜下大吉”，上逆而下顺也。”">​</a></h3><p>时宜用过，虽过正也。 失其所安者，必矫其所为以求安，过于自大，其势必危，过于自损，可以获吉，故曰“上逆而下顺，飞鸟之象”。</p><h3 id="象曰-山上有雷-小过-君子以行过乎恭-丧过乎哀-用过乎俭。" tabindex="-1">象曰：山上有雷，小过，君子以行过乎恭，丧过乎哀，用过乎俭。 <a class="header-anchor" href="#象曰-山上有雷-小过-君子以行过乎恭-丧过乎哀-用过乎俭。" aria-label="Permalink to “象曰：山上有雷，小过，君子以行过乎恭，丧过乎哀，用过乎俭。”">​</a></h3><p>过恭、哀、俭，皆宜下之义。</p><h3 id="初六-飞鸟以凶。-象曰-飞鸟以凶-不可如何也。" tabindex="-1">初六，飞鸟以凶。 象曰：“飞鸟以凶”，不可如何也。 <a class="header-anchor" href="#初六-飞鸟以凶。-象曰-飞鸟以凶-不可如何也。" aria-label="Permalink to “初六，飞鸟以凶。 象曰：“飞鸟以凶”，不可如何也。”">​</a></h3><h3 id="六二-过其祖-遇其妣-不及其君-遇其臣-无咎。-象曰-不及其君-臣不可过也。" tabindex="-1">六二，过其祖，遇其妣，不及其君，遇其臣，无咎。 象曰：“不及其君”，臣不可过也。 <a class="header-anchor" href="#六二-过其祖-遇其妣-不及其君-遇其臣-无咎。-象曰-不及其君-臣不可过也。" aria-label="Permalink to “六二，过其祖，遇其妣，不及其君，遇其臣，无咎。 象曰：“不及其君”，臣不可过也。”">​</a></h3><p>与其上比于阳，不若下遇于阴，与其上合于五，不若退附于初，宜下之义也。无应于上，故能免咎。臣居己下，犹不可过，况其他乎!</p><h3 id="九三-弗过防之-从或戕之-凶。-象曰-从或戕之-凶如何也" tabindex="-1">九三，弗过防之，从或戕之，凶。 象曰：“从或戕之”，凶如何也! <a class="header-anchor" href="#九三-弗过防之-从或戕之-凶。-象曰-从或戕之-凶如何也" aria-label="Permalink to “九三，弗过防之，从或戕之，凶。 象曰：“从或戕之”，凶如何也!”">​</a></h3><p>居阳以刚而应于上，为众所疾，非过为防慎，人或戕之，凶之甚也。</p><h3 id="九四-无咎-弗过遇之-往厉必戒-勿用永贞。-象曰-弗过遇之-位不当也-往厉必戒-终不可长也。" tabindex="-1">九四，无咎，弗过遇之，往厉必戒，勿用永贞。 象曰：“弗过遇之”，位不当也；“往厉必戒”，终不可长也。 <a class="header-anchor" href="#九四-无咎-弗过遇之-往厉必戒-勿用永贞。-象曰-弗过遇之-位不当也-往厉必戒-终不可长也。" aria-label="Permalink to “九四，无咎，弗过遇之，往厉必戒，勿用永贞。 象曰：“弗过遇之”，位不当也；“往厉必戒”，终不可长也。”">​</a></h3><p>道非刚亢，故无咎，有应于下，故曰“弗过遇之”。过此以往，难无以除，故危而必戒；不可当然，故勿用永贞。一云：九四以阳居阴而乘九三之刚，非其过也，乃适与之遇尔，故无咎；若率是而往， 必危以为戒，终不可久，故勿用永贞，当思奋尔。</p><h3 id="六五-密云不雨-自我西郊。公弋取彼在穴。-象曰-密云不雨-已上也。" tabindex="-1">六五，密云不雨，自我西郊。公弋取彼在穴。 象曰：“密云不雨”，已上也。 <a class="header-anchor" href="#六五-密云不雨-自我西郊。公弋取彼在穴。-象曰-密云不雨-已上也。" aria-label="Permalink to “六五，密云不雨，自我西郊。公弋取彼在穴。 象曰：“密云不雨”，已上也。”">​</a></h3><p>不能畜刚止健。凡言“自我西郊”，进而不已也。柔得中，小事吉，故曰“公弋取彼在穴”，非及物之功，且不能摧敌止暴也。三止于下，隐伏之象，故曰“在穴”。小过有飞鸟之象，故因曰“取彼在穴”。雨必蒸聚，自下而上，则其润泽周普，今自西而东，趋其所应，其施未光也。“已上”亦尚往之义。</p><h3 id="上六-弗遇过之-飞鸟离之-凶-是谓灾眚。-象曰-弗遇过之-已亢也。" tabindex="-1">上六，弗遇过之，飞鸟离之，凶，是谓灾眚。 象曰：“弗遇过之”，已亢也。 <a class="header-anchor" href="#上六-弗遇过之-飞鸟离之-凶-是谓灾眚。-象曰-弗遇过之-已亢也。" aria-label="Permalink to “上六，弗遇过之，飞鸟离之，凶，是谓灾眚。 象曰：“弗遇过之”，已亢也。”">​</a></h3><p>不宜上而上，乃自取之灾也。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
